/* runtime.c — the Heroes C runtime (design.md §4.20).
 *
 * M0: panic and integer printing. M5a: print's segment printers, and a panic
 * that flushes. M5b: `str`, reference counting, the leak counter, and canonical
 * `f64` rendering (panel 021). M5c: the descriptor ABI and `[T]` (panel 022).
 *
 * Per-type functions are generated by the COMPILER, not written here (§4.20):
 * C has no copy constructors or generic comparison, and a type-erased `void*`
 * runtime would void the "clang type-checks every call" property. So this file
 * holds only what the language cannot express.
 */

#include "heroes_runtime.h"

#include <locale.h>
#include <float.h>
#include <math.h>
#include <stdio.h>
#include <stdint.h>
#include <stdlib.h>
#include <string.h>
#include <xlocale.h>

_Noreturn void hero_panic(const char *msg) {
    fflush(stdout);
    fprintf(stderr, "panic: %s\n", msg);
    abort();
}
_Noreturn void hero_panic_overflow(void) { hero_panic("integer overflow"); }
_Noreturn void hero_unreachable(void) {
    hero_panic("entered unreachable code — this is a compiler bug, please report it");
}

void hero_print_int(int64_t v) { printf("%lld", (long long)v); }
void hero_print_bool(bool v) { fputs(v ? "true" : "false", stdout); }
void hero_print_end(void) { putchar('\n'); }

/* -- str ------------------------------------------------------------------- */

static const struct {
    HeroStrHeader h;
    char b[1];
} hero_empty_block = {{-1, HERO_STR_MAGIC}, ""};

HeroStr hero_str_empty(void) { return (HeroStr){hero_empty_block.b, 0}; }

/* The header sits immediately before the bytes. One helper, one place where the
 * pointer arithmetic lives. */
static HeroStrHeader *hero_str_hdr(HeroStr s) {
    return (HeroStrHeader *)(void *)((char *)(void *)(uintptr_t)s.ptr -
                                     sizeof(HeroStrHeader));
}

/* Every reader goes through this: a NULL ptr is an unassigned or moved-out
 * slot, and reading one is a compiler bug, not an empty string. */
static void hero_str_require(HeroStr s) {
    if (s.ptr == NULL) {
        hero_panic("read of an unassigned str slot — this is a compiler bug, please report it");
    }
}

/* live heap-block balance: the leak detector that works on this platform */
static int64_t hero_live_blocks = 0;
int64_t hero_runtime_live(void) { return hero_live_blocks; }
void hero_runtime_check_leaks(void) {
    if (hero_live_blocks != 0) {
        fflush(stdout);
        fprintf(stderr, "panic: %lld heap blocks still live at exit "
                        "(a missing decref) — this is a compiler bug\n",
                (long long)hero_live_blocks);
        abort();
    }
}

static HeroStr hero_str_alloc(int64_t len) {
    if (len < 0) hero_panic("negative string length");
    HeroStrHeader *h = malloc(sizeof(HeroStrHeader) + (size_t)len + 1);
    if (h == NULL) hero_panic("out of memory");
    h->refcount = 1;
    h->magic = HERO_STR_MAGIC;
    hero_live_blocks += 1;
    char *b = (char *)(void *)(h + 1);
    b[len] = '\0';
    return (HeroStr){b, len};
}

/* One place where a str block is validated. */
static HeroStrHeader *hero_str_hdr_checked(HeroStr s) {
    HeroStrHeader *h = hero_str_hdr(s);
    if (h->magic != HERO_STR_MAGIC) {
        hero_panic("not a Heroes string block — a str was fabricated from a "
                   "foreign pointer; use hero_str_from_bytes");
    }
    return h;
}

void hero_str_incref(HeroStr s) {
    if (s.ptr == NULL) return;
    HeroStrHeader *h = hero_str_hdr_checked(s);
    if (h->refcount < 0) return; /* static literal */
    h->refcount += 1;
}

void hero_str_decref(HeroStr s) {
    if (s.ptr == NULL) return; /* the zero-init non-value: a no-op */
    HeroStrHeader *h = hero_str_hdr_checked(s);
    if (h->refcount < 0) return; /* static literal */
    h->refcount -= 1;
    if (h->refcount == 0) {
        hero_live_blocks -= 1;
        free(h);
    }
}

HeroStr hero_str_concat(HeroStr a, HeroStr b) {
    hero_str_require(a);
    hero_str_require(b);
    if (a.len > INT64_MAX - b.len) hero_panic("string length overflow");
    HeroStr r = hero_str_alloc(a.len + b.len);
    char *w = (char *)(void *)(uintptr_t)r.ptr;
    memcpy(w, a.ptr, (size_t)a.len);
    memcpy(w + a.len, b.ptr, (size_t)b.len);
    return r;
}

bool hero_str_eq(HeroStr a, HeroStr b) {
    hero_str_require(a);
    hero_str_require(b);
    if (a.len != b.len) return false;
    return memcmp(a.ptr, b.ptr, (size_t)a.len) == 0;
}

int64_t hero_str_cmp(HeroStr a, HeroStr b) {
    hero_str_require(a);
    hero_str_require(b);
    int64_t n = a.len < b.len ? a.len : b.len;
    int c = n == 0 ? 0 : memcmp(a.ptr, b.ptr, (size_t)n);
    if (c != 0) return c < 0 ? -1 : 1;
    if (a.len == b.len) return 0;
    return a.len < b.len ? -1 : 1;
}

int64_t hero_str_len(HeroStr s) {
    hero_str_require(s);
    return s.len;
}

int64_t hero_str_byte(HeroStr s, int64_t i) {
    hero_str_require(s);
    if (i < 0 || i >= s.len) hero_panic("string index out of range");
    return (int64_t)(unsigned char)s.ptr[i];
}

HeroStr hero_str_slice(HeroStr s, int64_t from, int64_t to) {
    hero_str_require(s);
    if (from < 0 || to < from || to > s.len) hero_panic("string slice out of range");
    if (to == from) return hero_str_empty();
    HeroStr r = hero_str_alloc(to - from);
    memcpy((char *)(void *)(uintptr_t)r.ptr, s.ptr + from, (size_t)(to - from));
    return r;
}

void hero_print_str(HeroStr s) {
    hero_str_require(s);
    fwrite(s.ptr, 1, (size_t)s.len, stdout);
}

HeroStr hero_str_from_bytes(const char *p, int64_t len) {
    if (p == NULL) hero_panic("hero_str_from_bytes: NULL pointer from C");
    if (len == 0) return hero_str_empty();
    HeroStr r = hero_str_alloc(len);
    memcpy((char *)(void *)(uintptr_t)r.ptr, p, (size_t)len);
    return r;
}

HeroStr hero_str_from_cstr(const char *p) {
    if (p == NULL) hero_panic("hero_str_from_cstr: NULL pointer from C");
    return hero_str_from_bytes(p, (int64_t)strlen(p));
}

const char *hero_str_cstr(HeroStr s) {
    hero_str_require(s);
    return s.ptr; /* the NUL is already there: §4.20's zero-copy .cstr() */
}

/* -- f64 rendering (design.md §4.9, panel 021) -----------------------------
 *
 * ROUND-TRIP-EXACT, never "shortest": %.*g at increasing precision until
 * strtod() reads back the same bits. The distinction is not pedantic — 5e-324
 * renders 4.94065645841247e-324, which round-trips and is not the shortest
 * decimal, and Java shipped 1.9999999999999998E23 for eighteen years before
 * Schubfach to prove it matters.
 *
 * The subnormal branch is gnulib's, whose ftoastr is the widely-shipped
 * implementation of this technique (coreutils, Emacs): below DBL_MIN the loop
 * starts at precision 1, because %.15g of 1e-323 is
 * 9.88131291682493e-324 — fifteen significant digits for a value Python
 * renders 1e-323.
 *
 * LOCALE IS REMOVED STRUCTURALLY, not promised away. Under de_DE.UTF-8 the
 * ladder emits the malformed `0,1.0` — the decimal-point rider finds no `.` and
 * appends one — and the round-trip check CANNOT SEE IT, because strtod reads
 * the same locale and is wrong consistently. `setlocale` is process-wide and
 * §1.11 guarantees every real program links C libraries: gettext, glib and
 * ncurses all call it, and `extern function setlocale(...)` is one line of
 * Heroes. So the render runs inside a "C" locale window, which covers snprintf
 * AND strtod at once. PEP 331 is the shape of the hazard: CPython never called
 * setlocale, GTK+ did, CPython broke anyway. */

/* Created once, never destroyed: the process needs exactly one. */
static locale_t hero_c_locale(void) {
    static locale_t cached = (locale_t)0;
    if (cached == (locale_t)0) {
        cached = newlocale(LC_ALL_MASK, "C", (locale_t)0);
    }
    return cached;
}

static int hero_f64_render(char *buf, size_t cap, double v) {
    if (v != v) return snprintf(buf, cap, "nan");
    if (v == (double)INFINITY) return snprintf(buf, cap, "inf");
    if (v == -(double)INFINITY) return snprintf(buf, cap, "-inf");

    locale_t c = hero_c_locale();
    locale_t previous = (locale_t)0;
    if (c != (locale_t)0) previous = uselocale(c);

    double magnitude = v < 0 ? -v : v;
    int first = magnitude != 0.0 && magnitude < DBL_MIN ? 1 : DBL_DIG;
    int n = 0;
    for (int prec = first; prec <= 17; prec++) {
        n = snprintf(buf, cap, "%.*g", prec, v);
        if (n < 0 || (size_t)n >= cap) hero_panic("f64 render overflow");
        if (strtod(buf, NULL) == v) break;
    }
    /* The rider: a value with no fractional part still shows a point, so
     * print(1.0) is not indistinguishable from print(1). Under `1`, the
     * programs `print(price * to_f64(count))` and `print(5 * 2)` would emit
     * identical bytes and an accidental int->f64 drift would stay green in
     * every golden — which is what §4.3's no-implicit-conversions rule exists
     * to prevent. */
    if (strpbrk(buf, ".eE") == NULL) {
        int m = snprintf(buf + n, cap - (size_t)n, ".0");
        if (m < 0 || (size_t)(n + m) >= cap) hero_panic("f64 render overflow");
        n += m;
    }
    if (previous != (locale_t)0) uselocale(previous);
    return n;
}

void hero_print_f64(double v) {
    char buf[40];
    (void)hero_f64_render(buf, sizeof buf, v);
    fputs(buf, stdout);
}

HeroStr hero_f64_to_str(double v) {
    char buf[40];
    int n = hero_f64_render(buf, sizeof buf, v);
    HeroStr r = hero_str_alloc(n);
    memcpy((char *)(void *)(uintptr_t)r.ptr, buf, (size_t)n);
    return r;
}

HeroStr hero_int_to_str(int64_t v) {
    char buf[24];
    int n = snprintf(buf, sizeof buf, "%lld", (long long)v);
    HeroStr r = hero_str_alloc(n);
    memcpy((char *)(void *)(uintptr_t)r.ptr, buf, (size_t)n);
    return r;
}

HeroStr hero_bool_to_str(bool v) {
    /* static blocks: to_str of a bool allocates nothing */
    static const struct { HeroStrHeader h; char b[5]; } t = {{-1, HERO_STR_MAGIC}, "true"};
    static const struct { HeroStrHeader h; char b[6]; } f = {{-1, HERO_STR_MAGIC}, "false"};
    return v ? (HeroStr){t.b, 4} : (HeroStr){f.b, 5};
}

/* `to_str` of a `str` is the identity, and it must still hand back a reference so
 * that the caller's uniform "a call returns +1" rule holds. */
HeroStr hero_str_identity(HeroStr s) {
    hero_str_require(s);
    hero_str_incref(s);
    return s;
}

/* -- the descriptor ABI: the four scalars the compiler never declares --------
 *
 * Written here rather than generated because the compiler has no declaration to
 * generate them from, and because there is exactly one right answer per scalar:
 * a plain assignment, no drop, C's own `==`, and a hash that is a function of
 * the bytes THAT MATTER — which for `f64` means going through the bit pattern,
 * and for `bool` means normalising, since a `_Bool` can only be 0 or 1 but the
 * padding around it in an array element cannot be assumed. */

static void hero_copy_int(void *dst, const void *src) { *(int64_t *)dst = *(const int64_t *)src; }
static void hero_drop_nothing(void *elem) { (void)elem; }
static bool hero_eq_int(const void *a, const void *b) {
    return *(const int64_t *)a == *(const int64_t *)b;
}
/* FNV-1a over the eight bytes: one function, and the same one `toolchain.rs`
 * uses for the build cache, so there is one hash in this project rather than
 * two that drift. */
static uint64_t hero_hash_bytes(const void *p, size_t n) {
    const unsigned char *b = p;
    uint64_t h = UINT64_C(0xcbf29ce484222325);
    for (size_t i = 0; i < n; i++) {
        h ^= b[i];
        h *= UINT64_C(0x100000001b3);
    }
    return h;
}
static uint64_t hero_hash_int(const void *elem) { return hero_hash_bytes(elem, sizeof(int64_t)); }

static void hero_copy_f64(void *dst, const void *src) { *(double *)dst = *(const double *)src; }
static bool hero_eq_f64(const void *a, const void *b) {
    return *(const double *)a == *(const double *)b;
}
/* Through the bits, and NOT through the double: -0.0 == 0.0 is true while their
 * bit patterns differ, so hashing the bytes of a double would give two equal
 * values two hashes. Normalising the zero is what keeps eq and hash agreeing —
 * the invariant a map depends on. */
static uint64_t hero_hash_f64(const void *elem) {
    double v = *(const double *)elem;
    if (v == 0.0) v = 0.0; /* collapses -0.0 */
    return hero_hash_bytes(&v, sizeof v);
}

static void hero_copy_bool(void *dst, const void *src) { *(bool *)dst = *(const bool *)src; }
static bool hero_eq_bool(const void *a, const void *b) {
    return *(const bool *)a == *(const bool *)b;
}
static uint64_t hero_hash_bool(const void *elem) {
    unsigned char one = *(const bool *)elem ? 1u : 0u;
    return hero_hash_bytes(&one, 1);
}

static void hero_copy_str(void *dst, const void *src) {
    HeroStr s = *(const HeroStr *)src;
    hero_str_incref(s);
    *(HeroStr *)dst = s;
}
static void hero_drop_str(void *elem) { hero_str_decref(*(HeroStr *)elem); }
static bool hero_eq_str(const void *a, const void *b) {
    return hero_str_eq(*(const HeroStr *)a, *(const HeroStr *)b);
}
static uint64_t hero_hash_str(const void *elem) {
    HeroStr s = *(const HeroStr *)elem;
    hero_str_require(s);
    return hero_hash_bytes(s.ptr, (size_t)s.len);
}

const HeroDesc hero_desc_int = {sizeof(int64_t), hero_copy_int, hero_drop_nothing,
                                hero_eq_int, hero_hash_int};
const HeroDesc hero_desc_f64 = {sizeof(double), hero_copy_f64, hero_drop_nothing,
                                hero_eq_f64, hero_hash_f64};
const HeroDesc hero_desc_bool = {sizeof(bool), hero_copy_bool, hero_drop_nothing,
                                 hero_eq_bool, hero_hash_bool};
const HeroDesc hero_desc_str = {sizeof(HeroStr), hero_copy_str, hero_drop_str,
                                hero_eq_str, hero_hash_str};

/* -- the array -------------------------------------------------------------- */

/* Declared here, defined after the array functions they call. */
static void hero_copy_array(void *dst, const void *src);
static void hero_drop_array(void *elem);
static bool hero_eq_array(const void *a, const void *b);
static uint64_t hero_hash_array(const void *elem);

const HeroDesc hero_desc_array = {sizeof(HeroArrayHeader *), hero_copy_array,
                                  hero_drop_array, hero_eq_array, hero_hash_array};

static unsigned char *hero_array_data(HeroArrayHeader *a) {
    return (unsigned char *)(void *)(a + 1);
}
static const unsigned char *hero_array_data_const(const HeroArrayHeader *a) {
    return (const unsigned char *)(const void *)(a + 1);
}

/* Every reader goes through this: NULL is an unassigned or moved-out slot, and
 * reading one is a compiler bug, not an empty array. */
static void hero_array_require(const HeroArrayHeader *a) {
    if (a == NULL) {
        hero_panic("read of an unassigned array slot — this is a compiler bug, please report it");
    }
}

HeroArrayHeader *hero_array_new(const HeroDesc *elem, int64_t cap) {
    if (elem == NULL) hero_panic("array with no element descriptor — a compiler bug");
    if (elem->hash == NULL) hero_panic("element descriptor with no hash — a compiler bug");
    if (cap < 1) cap = 1;
    if ((uint64_t)cap > (SIZE_MAX - sizeof(HeroArrayHeader)) / elem->size) {
        hero_panic("array too large");
    }
    HeroArrayHeader *a = malloc(sizeof(HeroArrayHeader) + (size_t)cap * elem->size);
    if (a == NULL) hero_panic("out of memory");
    a->refcount = 1;
    a->len = 0;
    a->cap = cap;
    a->elem = elem;
    hero_live_blocks += 1;
    return a;
}

void hero_array_incref(HeroArrayHeader *a) {
    if (a == NULL) return;
    a->refcount += 1;
}

void hero_array_decref(HeroArrayHeader *a) {
    if (a == NULL) return; /* the zero-init non-value: a no-op */
    a->refcount -= 1;
    if (a->refcount > 0) return;
    unsigned char *data = hero_array_data(a);
    for (int64_t i = 0; i < a->len; i++) {
        a->elem->drop(data + (size_t)i * a->elem->size);
    }
    hero_live_blocks -= 1;
    free(a);
}

int64_t hero_array_len(const HeroArrayHeader *a) {
    hero_array_require(a);
    return a->len;
}

const void *hero_array_at(const HeroArrayHeader *a, int64_t index) {
    hero_array_require(a);
    if (index < 0 || index >= a->len) hero_panic("array index out of range");
    return hero_array_data_const(a) + (size_t)index * a->elem->size;
}

HeroArrayHeader *hero_array_push(const HeroArrayHeader *a, const void *elem) {
    hero_array_require(a);
    if (a->len == INT64_MAX) hero_panic("array length overflow");
    HeroArrayHeader *b = hero_array_new(a->elem, a->len + 1);
    const unsigned char *src = hero_array_data_const(a);
    unsigned char *dst = hero_array_data(b);
    size_t size = a->elem->size;
    for (int64_t i = 0; i < a->len; i++) {
        a->elem->copy(dst + (size_t)i * size, src + (size_t)i * size);
    }
    /* The new element is copied in, not moved: the caller's value is borrowed
     * (every value reaching a call is, by the ownership pass's rule 5), so the
     * array takes its own reference exactly as it does for the ones it copied. */
    a->elem->copy(dst + (size_t)a->len * size, elem);
    b->len = a->len + 1;
    return b;
}

bool hero_array_eq(const HeroArrayHeader *a, const HeroArrayHeader *b) {
    hero_array_require(a);
    hero_array_require(b);
    if (a->len != b->len) return false;
    if (a == b) return true;
    const unsigned char *da = hero_array_data_const(a);
    const unsigned char *db = hero_array_data_const(b);
    size_t size = a->elem->size;
    for (int64_t i = 0; i < a->len; i++) {
        if (!a->elem->eq(da + (size_t)i * size, db + (size_t)i * size)) return false;
    }
    return true;
}

/* One descriptor for every `[T]`: these four reach the element type through the
 * header, so nothing here depends on what the array holds. */
static void hero_copy_array(void *dst, const void *src) {
    HeroArrayHeader *a = *(HeroArrayHeader *const *)src;
    hero_array_incref(a);
    *(HeroArrayHeader **)dst = a;
}
static void hero_drop_array(void *elem) { hero_array_decref(*(HeroArrayHeader **)elem); }
static bool hero_eq_array(const void *a, const void *b) {
    return hero_array_eq(*(HeroArrayHeader *const *)a, *(HeroArrayHeader *const *)b);
}
/* An array is hashable so that a descriptor's `hash` is never null (panel 022),
 * not because an array can be a map key — `{[int]: v}` is a question §4.9 has
 * not answered. Order matters, because `==` on an array is order-sensitive. */
static uint64_t hero_hash_array(const void *elem) {
    const HeroArrayHeader *a = *(const HeroArrayHeader *const *)elem;
    hero_array_require(a);
    uint64_t h = UINT64_C(0xcbf29ce484222325);
    const unsigned char *data = hero_array_data_const(a);
    for (int64_t i = 0; i < a->len; i++) {
        uint64_t one = a->elem->hash(data + (size_t)i * a->elem->size);
        h ^= one;
        h *= UINT64_C(0x100000001b3);
    }
    return h;
}

/* -- copy-on-write ---------------------------------------------------------- */

void hero_array_unshare(HeroArrayHeader **slot) {
    if (slot == NULL) hero_panic("unshare of no slot — a compiler bug");
    HeroArrayHeader *a = *slot;
    hero_array_require(a);
    /* Unique already: mutating in place is unobservable, which is the whole point
     * of copy-on-write. */
    if (a->refcount == 1) return;
    HeroArrayHeader *b = hero_array_new(a->elem, a->len > 0 ? a->len : 1);
    const unsigned char *src = hero_array_data_const(a);
    unsigned char *dst = hero_array_data(b);
    size_t size = a->elem->size;
    for (int64_t i = 0; i < a->len; i++) {
        /* SHALLOW plus incref, per element: the copy shares whatever the elements
         * point at, and that sharing is why the *next* step of the place path has
         * to unshare too. Copying deeply here would make the per-step rule
         * unnecessary and pay for every binding what only a mutation costs. */
        a->elem->copy(dst + (size_t)i * size, src + (size_t)i * size);
    }
    b->len = a->len;
    *slot = b;
    hero_array_decref(a);
}

void *hero_array_at_mut(HeroArrayHeader *a, int64_t index) {
    hero_array_require(a);
    if (index < 0 || index >= a->len) hero_panic("array index out of range");
    return hero_array_data(a) + (size_t)index * a->elem->size;
}

void hero_array_set(HeroArrayHeader **slot, int64_t index, const void *value) {
    if (slot == NULL) hero_panic("store into no slot — a compiler bug");
    if (value == NULL) hero_panic("store of no value — a compiler bug");
    /* Bounds first, so an out-of-range write aborts without paying for a copy —
     * and so the abort says the same thing whether or not the array was shared. */
    hero_array_require(*slot);
    if (index < 0 || index >= (*slot)->len) hero_panic("array index out of range");
    hero_array_unshare(slot);
    HeroArrayHeader *a = *slot;
    unsigned char *place = hero_array_data(a) + (size_t)index * a->elem->size;
    /* Release what was there, then MOVE the caller's reference in. No copy: the
     * caller increfed before this call, which is what lets the value be something
     * that lived inside the container the unshare just copied. */
    a->elem->drop(place);
    memcpy(place, value, a->elem->size);
}

/* -- the failure side of `T?` ----------------------------------------------- */

void hero_failure_retain(const HeroFailure *v) {
    hero_str_incref(v->code);
    hero_str_incref(v->msg);
}

void hero_failure_release(HeroFailure *v) {
    hero_str_decref(v->code);
    hero_str_decref(v->msg);
}

bool hero_failure_eq(const HeroFailure *a, const HeroFailure *b) {
    /* The code first: §4.6 says a code is stable and a message is not, so a
     * comparison that short-circuits on the code is the one that keeps meaning
     * when somebody rewords the message. */
    return hero_str_eq(a->code, b->code) && hero_str_eq(a->msg, b->msg);
}

uint64_t hero_failure_hash(const void *elem) {
    const HeroFailure *v = elem;
    uint64_t h = hero_hash_str(&v->code);
    return (h ^ hero_hash_str(&v->msg)) * UINT64_C(0x100000001b3);
}

static void hero_copy_failure(void *dst, const void *src) {
    const HeroFailure *s = src;
    hero_failure_retain(s);
    *(HeroFailure *)dst = *s;
}
static void hero_drop_failure(void *elem) { hero_failure_release(elem); }
static bool hero_eq_failure(const void *a, const void *b) { return hero_failure_eq(a, b); }

const HeroDesc hero_desc_failure = {sizeof(HeroFailure), hero_copy_failure,
                                    hero_drop_failure, hero_eq_failure,
                                    hero_failure_hash};

HeroFailure hero_failure_missing_key(void) {
    static const struct { HeroStrHeader h; char b[12]; } code = {
        {-1, HERO_STR_MAGIC}, "missing_key"};
    static const struct { HeroStrHeader h; char b[12]; } msg = {
        {-1, HERO_STR_MAGIC}, "no such key"};
    return (HeroFailure){{code.b, 11}, {msg.b, 11}};
}

/* -- the map ---------------------------------------------------------------- */

/* Every region starts at a multiple of this, so no element is ever misaligned
 * whatever the descriptors say. `max_align_t` is the widest thing C can ask for,
 * which is the only alignment a runtime that does not know its element types can
 * honestly promise. */
#define HERO_MAP_ALIGN (_Alignof(max_align_t))

static size_t hero_map_round_up(size_t n) {
    size_t a = HERO_MAP_ALIGN;
    return (n + a - 1) / a * a;
}

static unsigned char *hero_map_states(HeroMapHeader *m) {
    return (unsigned char *)(void *)m + m->states;
}
static const unsigned char *hero_map_states_const(const HeroMapHeader *m) {
    return (const unsigned char *)(const void *)m + m->states;
}
static unsigned char *hero_map_key_at(HeroMapHeader *m, int64_t at) {
    return (unsigned char *)(void *)m + m->keys + (size_t)at * m->key->size;
}
static const unsigned char *hero_map_key_at_const(const HeroMapHeader *m, int64_t at) {
    return (const unsigned char *)(const void *)m + m->keys + (size_t)at * m->key->size;
}
static unsigned char *hero_map_val_at(HeroMapHeader *m, int64_t at) {
    return (unsigned char *)(void *)m + m->vals + (size_t)at * m->val->size;
}
static const unsigned char *hero_map_val_at_const(const HeroMapHeader *m, int64_t at) {
    return (const unsigned char *)(const void *)m + m->vals + (size_t)at * m->val->size;
}

static void hero_map_require(const HeroMapHeader *m) {
    if (m == NULL) {
        hero_panic("read of an unassigned map slot — this is a compiler bug, please report it");
    }
}

/* THE FIXED SEED. Mixed into every probe so that the bucket a key lands in is a
 * function of the key alone — which is what makes iteration order, and therefore
 * generated C, reproducible across runs (panel 006). */
#define HERO_MAP_SEED UINT64_C(0x9e3779b97f4a7c15)

static int64_t hero_map_slot_of(const HeroMapHeader *m, const void *key) {
    uint64_t h = m->key->hash(key) ^ HERO_MAP_SEED;
    return (int64_t)(h & (uint64_t)(m->cap - 1));
}

HeroMapHeader *hero_map_new(const HeroDesc *key, const HeroDesc *val, int64_t entries) {
    if (key == NULL || val == NULL) hero_panic("map with no descriptor — a compiler bug");
    if (key->hash == NULL) hero_panic("map key descriptor with no hash — a compiler bug");
    if (entries < 0) hero_panic("negative map size");
    /* Load factor at most 1/2, and never zero buckets: linear probing needs a hole
     * to terminate on, and `cap > len` is what guarantees one exists. */
    int64_t cap = 4;
    while (cap < entries * 2 + 1) {
        if (cap > INT64_MAX / 2) hero_panic("map too large");
        cap *= 2;
    }
    size_t head = hero_map_round_up(sizeof(HeroMapHeader));
    size_t states = hero_map_round_up((size_t)cap);
    size_t keys = hero_map_round_up((size_t)cap * key->size);
    size_t vals = (size_t)cap * val->size;
    HeroMapHeader *m = malloc(head + states + keys + vals);
    if (m == NULL) hero_panic("out of memory");
    m->refcount = 1;
    m->len = 0;
    m->cap = cap;
    m->key = key;
    m->val = val;
    m->states = head;
    m->keys = head + states;
    m->vals = head + states + keys;
    memset(hero_map_states(m), 0, (size_t)cap);
    hero_live_blocks += 1;
    return m;
}

void hero_map_incref(HeroMapHeader *m) {
    if (m == NULL) return;
    m->refcount += 1;
}

void hero_map_decref(HeroMapHeader *m) {
    if (m == NULL) return;
    m->refcount -= 1;
    if (m->refcount > 0) return;
    const unsigned char *states = hero_map_states_const(m);
    for (int64_t i = 0; i < m->cap; i++) {
        if (states[i] == 0) continue;
        m->key->drop(hero_map_key_at(m, i));
        m->val->drop(hero_map_val_at(m, i));
    }
    hero_live_blocks -= 1;
    free(m);
}

int64_t hero_map_len(const HeroMapHeader *m) {
    hero_map_require(m);
    return m->len;
}

void hero_map_put(HeroMapHeader *m, const void *key, const void *value) {
    hero_map_require(m);
    unsigned char *states = hero_map_states(m);
    int64_t at = hero_map_slot_of(m, key);
    for (int64_t probe = 0; probe < m->cap; probe++) {
        int64_t i = (at + probe) & (m->cap - 1);
        if (states[i] == 0) {
            /* COPY, not move — the same rule as `hero_array_push`, and for the same
             * reason: every value reaching a constructor is borrowed (the ownership
             * pass's rule 5), so the container has to take its own reference. */
            m->key->copy(hero_map_key_at(m, i), key);
            m->val->copy(hero_map_val_at(m, i), value);
            states[i] = 1;
            m->len += 1;
            return;
        }
        if (m->key->eq(hero_map_key_at_const(m, i), key)) {
            /* A duplicate key REPLACES: `{"a": 1, "a": 2}` has to mean something, and
             * the later entry is what a reader of the literal expects. The key that
             * later entry is what a reader of the literal expects. Only the VALUE is
             * replaced: the keys are equal, so which of the two copies the map keeps is
             * unobservable, and keeping the first saves a write and a reference. */
            m->val->drop(hero_map_val_at(m, i));
            m->val->copy(hero_map_val_at(m, i), value);
            return;
        }
    }
    /* `cap > 2 * len` is maintained by `hero_map_new`, so a literal cannot fill its
     * own table. Reaching here means the invariant broke. */
    hero_panic("map is full — this is a compiler bug, please report it");
}

const void *hero_map_find(const HeroMapHeader *m, const void *key) {
    hero_map_require(m);
    const unsigned char *states = hero_map_states_const(m);
    int64_t at = hero_map_slot_of(m, key);
    for (int64_t probe = 0; probe < m->cap; probe++) {
        int64_t i = (at + probe) & (m->cap - 1);
        /* An empty bucket ends the probe: with no deletion there are no tombstones,
         * so a hole means the key was never inserted. */
        if (states[i] == 0) return NULL;
        if (m->key->eq(hero_map_key_at_const(m, i), key)) {
            return hero_map_val_at_const(m, i);
        }
    }
    return NULL;
}

bool hero_map_eq(const HeroMapHeader *a, const HeroMapHeader *b) {
    hero_map_require(a);
    hero_map_require(b);
    if (a->len != b->len) return false;
    if (a == b) return true;
    const unsigned char *states = hero_map_states_const(a);
    for (int64_t i = 0; i < a->cap; i++) {
        if (states[i] == 0) continue;
        const void *found = hero_map_find(b, hero_map_key_at_const(a, i));
        if (found == NULL) return false;
        if (!a->val->eq(hero_map_val_at_const(a, i), found)) return false;
    }
    return true;
}

/* One descriptor for every `{K: V}`, for the same reason as the array's: copy, drop
 * and eq on a map value reach the key and value types through the header. */
static void hero_copy_map(void *dst, const void *src) {
    HeroMapHeader *m = *(HeroMapHeader *const *)src;
    hero_map_incref(m);
    *(HeroMapHeader **)dst = m;
}
static void hero_drop_map(void *elem) { hero_map_decref(*(HeroMapHeader **)elem); }
static bool hero_eq_map(const void *a, const void *b) {
    return hero_map_eq(*(HeroMapHeader *const *)a, *(HeroMapHeader *const *)b);
}
/* Order-INDEPENDENT, and it has to be: `eq` ignores insertion order, so a hash that
 * did not would give two equal maps two hashes. XOR of the per-entry mixes is
 * commutative, which is the cheapest way to say that. */
static uint64_t hero_hash_map(const void *elem) {
    const HeroMapHeader *m = *(const HeroMapHeader *const *)elem;
    hero_map_require(m);
    const unsigned char *states = hero_map_states_const(m);
    uint64_t h = 0;
    for (int64_t i = 0; i < m->cap; i++) {
        if (states[i] == 0) continue;
        uint64_t k = m->key->hash(hero_map_key_at_const(m, i));
        uint64_t v = m->val->hash(hero_map_val_at_const(m, i));
        h ^= (k ^ (v * UINT64_C(0x100000001b3)));
    }
    return h ^ (uint64_t)m->len;
}

const HeroDesc hero_desc_map = {sizeof(HeroMapHeader *), hero_copy_map, hero_drop_map,
                                hero_eq_map, hero_hash_map};

_Noreturn void hero_panic_must(HeroFailure f) {
    /* Built by hand rather than through `hero_panic`, so the two strings print
     * without needing a NUL-terminated join: a `HeroStr` always has its NUL, but
     * `code` and `msg` come from the program and one `fprintf` is one write. */
    fflush(stdout);
    fprintf(stderr, "panic: .must() on an error: %s: %s\n",
            hero_str_cstr(f.code), hero_str_cstr(f.msg));
    abort();
}

HeroArrayHeader *hero_map_keys(const HeroMapHeader *m) {
    hero_map_require(m);
    HeroArrayHeader *out = hero_array_new(m->key, m->len > 0 ? m->len : 1);
    const unsigned char *states = hero_map_states_const(m);
    unsigned char *data = (unsigned char *)(void *)(out + 1);
    int64_t at = 0;
    for (int64_t i = 0; i < m->cap; i++) {
        if (states[i] == 0) continue;
        /* Copied, not moved: the map keeps its own key and the array takes one. */
        m->key->copy(data + (size_t)at * m->key->size, hero_map_key_at_const(m, i));
        at += 1;
    }
    out->len = at;
    return out;
}

/* Grow and re-probe, through the PUBLIC copy path.
 *
 * Written first as `memcpy` of the live entries plus `free` of the old block
 * without dropping — the reasoning being that the references pass to the new block
 * unchanged, so no descriptor should run. That reasoning is right about the
 * references and wrong about everything else: it hand-rolls refcount bookkeeping in
 * a second place, and the first program to grow a map and then read its keys
 * panicked with `not a Heroes string block`, every printed answer correct and the
 * failure at exit.
 *
 * This version copies through `hero_map_put` (+1 per entry, via the descriptors)
 * and releases the old map through `hero_map_decref` (−1 per entry, via the same
 * descriptors). Balanced by construction, with no arithmetic of mine in it. A
 * growth costs one extra copy of every entry, and a rehash was already paying for
 * one. */
static HeroMapHeader *hero_map_grown(HeroMapHeader *m) {
    HeroMapHeader *b = hero_map_new(m->key, m->val, m->len * 2 + 1);
    const unsigned char *states = hero_map_states_const(m);
    for (int64_t i = 0; i < m->cap; i++) {
        if (states[i] == 0) continue;
        hero_map_put(b, hero_map_key_at_const(m, i), hero_map_val_at_const(m, i));
    }
    hero_map_decref(m);
    return b;
}

void hero_map_set(HeroMapHeader **slot, const void *key, const void *value) {
    if (slot == NULL) hero_panic("store into no map — a compiler bug");
    hero_map_require(*slot);
    HeroMapHeader *m = *slot;
    unsigned char *states = hero_map_states(m);
    int64_t at = hero_map_slot_of(m, key);
    for (int64_t probe = 0; probe < m->cap; probe++) {
        int64_t i = (at + probe) & (m->cap - 1);
        if (states[i] == 0) {
            /* Load factor at most 1/2, the invariant `hero_map_new` establishes and
             * this is the only place that can break it. Grow first, then retry from
             * the top: the bucket for this key is different in the new table. */
            if ((m->len + 1) * 2 > m->cap) {
                *slot = hero_map_grown(m);
                hero_map_set(slot, key, value);
                return;
            }
            m->key->copy(hero_map_key_at(m, i), key);
            m->val->copy(hero_map_val_at(m, i), value);
            states[i] = 1;
            m->len += 1;
            return;
        }
        if (m->key->eq(hero_map_key_at_const(m, i), key)) {
            /* Replace the value in place and keep the key that is there — they are
             * equal, so which copy the map holds is unobservable. */
            m->val->drop(hero_map_val_at(m, i));
            m->val->copy(hero_map_val_at(m, i), value);
            return;
        }
    }
    hero_panic("map is full — this is a compiler bug, please report it");
}
